import{_ as t,o,c as a,a2 as n}from"./chunks/framework.Dkj3JE0_.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/CFA/Quiz/C0 Ethics/misses.md","filePath":"blogs/CFA/Quiz/C0 Ethics/misses.md"}'),s={name:"blogs/CFA/Quiz/C0 Ethics/misses.md"};function r(i,e,l,c,p,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h2 id="_2026-10-12-—-i-a-knowledge-of-the-law" tabindex="-1">2026-10-12 — I(A) Knowledge of the Law <a class="header-anchor" href="#_2026-10-12-—-i-a-knowledge-of-the-law" aria-label="Permalink to &quot;2026-10-12 — I(A) Knowledge of the Law&quot;">​</a></h2><p><strong>Q:</strong> When applicable law and the Code &amp; Standards conflict, which do you follow — and what’s the one-line rule?</p><p><strong>My answer:</strong> Follow the stricter. (Did not know the one-line rule.)</p><p><strong>Correct:</strong> Follow the <strong>stricter</strong> of applicable law vs Code &amp; Standards. One-line rule: <em>Know and comply with the stricter requirement; do not knowingly assist in any violation — dissociate if necessary.</em></p><p><strong>Gap:</strong> One-line rule / dissociation framing incomplete.</p><h2 id="_2026-10-12-—-i-a-ns-ls-ms-map" tabindex="-1">2026-10-12 — I(A) NS / LS / MS map <a class="header-anchor" href="#_2026-10-12-—-i-a-ns-ls-ms-map" aria-label="Permalink to &quot;2026-10-12 — I(A) NS / LS / MS map&quot;">​</a></h2><p><strong>Q:</strong> In a multi-jurisdiction setting, what do NS / LS / MS mean for which rule you follow?</p><p><strong>My answer:</strong> No securities law / Less strict / More strict. “The MS one.”</p><p><strong>Correct map:</strong></p><ul><li><strong>NS</strong> (no applicable securities law) → follow <strong>Code &amp; Standards</strong></li><li><strong>LS</strong> (law less strict than Code) → follow <strong>Code &amp; Standards</strong></li><li><strong>MS</strong> (law more strict than Code) → follow <strong>the law</strong></li></ul><p><strong>Gap:</strong> Named the acronyms but did not state which rule applies in each case (only gestured at MS).</p><h2 id="_2026-10-12-—-i-b-gifts-vs-inducements-ipo-allocations" tabindex="-1">2026-10-12 — I(B) Gifts vs inducements / IPO allocations <a class="header-anchor" href="#_2026-10-12-—-i-b-gifts-vs-inducements-ipo-allocations" aria-label="Permalink to &quot;2026-10-12 — I(B) Gifts vs inducements / IPO allocations&quot;">​</a></h2><p><strong>Q:</strong> Client gifts vs third-party inducements — what’s allowed, and are personal allocations from oversubscribed IPOs OK?</p><p><strong>My answer:</strong> Depends on value; key is not damaging independence. Expensive client gifts before work generally not OK; after work may be OK with disclosure + boss approval (loyalty). Third-party expensive gifts generally not OK.</p><p><strong>Correct extras:</strong></p><ul><li>Client gifts: often OK if disclosed / within policy and do not compromise independence; timing and size matter.</li><li>Third-party inducements: presume conflict — decline / firm policy; especially if meant to influence.</li><li><strong>Personal allocations from oversubscribed IPOs: banned</strong> (not an OK “gift”).</li></ul><p><strong>Gap:</strong> Did not address the IPO allocation ban.</p><h2 id="_2026-10-12-—-i-b-issuer-paid-research" tabindex="-1">2026-10-12 — I(B) Issuer-paid research <a class="header-anchor" href="#_2026-10-12-—-i-b-issuer-paid-research" aria-label="Permalink to &quot;2026-10-12 — I(B) Issuer-paid research&quot;">​</a></h2><p><strong>Q:</strong> Issuer-paid research — what fee arrangement is acceptable, and what’s the independence trap?</p><p><strong>My answer:</strong> Necessary items like normal travel/accommodation OK; obvious “gifts” not OK. Did not know the trap. (Answered travel/gifts instead of issuer-paid research.)</p><p><strong>Correct:</strong></p><ul><li>Acceptable: <strong>flat fee</strong> only (not contingent on conclusions / rating).</li><li>Trap: pay tied to favorable research, or compensation structure that buys the opinion (pay-to-play). Disclose issuer-paid nature.</li></ul><p><strong>Gap:</strong> Missed flat-fee rule and contingent-fee independence trap; conflated with travel/gift rules.</p><h2 id="_2026-10-14-—-ii-a-mosaic-documentation" tabindex="-1">2026-10-14 — II(A) Mosaic documentation <a class="header-anchor" href="#_2026-10-14-—-ii-a-mosaic-documentation" aria-label="Permalink to &quot;2026-10-14 — II(A) Mosaic documentation&quot;">​</a></h2><p><strong>Q:</strong> Mosaic theory under II(A): can you issue a sell from public filings plus nonmaterial private color, and what should you do to protect yourself if challenged?</p><p><strong>My answer:</strong> Yes — can use nonpublic nonmaterial + all public material under mosaic. Did not know how to protect yourself.</p><p><strong>Correct:</strong> Mosaic is allowed. Protect yourself by <strong>documenting</strong> the public + nonmaterial nonpublic sources (also ties to V(C) Record Retention).</p><p><strong>Gap:</strong> Knew mosaic OK; forgot documentation / evidence trail.</p><h2 id="_2026-10-20-—-iii-b-fair-dealing-rating-change-preview-partial-block-fills" tabindex="-1">2026-10-20 — III(B) Fair Dealing: rating-change preview, partial block fills <a class="header-anchor" href="#_2026-10-20-—-iii-b-fair-dealing-rating-change-preview-partial-block-fills" aria-label="Permalink to &quot;2026-10-20 — III(B) Fair Dealing: rating-change preview, partial block fills&quot;">​</a></h2><p><strong>Q1:</strong> An analyst previews the firm’s own rating change to its largest clients before release. Which standard is breached?</p><p><strong>My answer:</strong> II(A) Material Nonpublic Information.</p><p><strong>Correct:</strong> <strong>III(B) Fair Dealing.</strong> The firm’s own recommendation change is not issuer information; the violation is <strong>selective dissemination</strong> (Example 1, Bradley Ames).</p><p><strong>Gap:</strong> Confused selective dissemination of the firm’s own research with MNPI.</p><p><strong>Q2:</strong> How should a partially filled block order be allocated?</p><p><strong>My answer:</strong> Case by case.</p><p><strong>Correct:</strong> <strong>Pro rata</strong>, every account at the <strong>same average price</strong>, under a <strong>written trade-allocation policy</strong>; adjustments for minimum lot sizes are allowed (Example 7, Hampton).</p><p><strong>Gap:</strong> Did not know the pro rata / same-price rule for partial fills.</p><h2 id="_2026-10-23-—-toffler-parents-ipo-note-not-a-miss" tabindex="-1">2026-10-23 — Toffler parents&#39; IPO (note, not a miss) <a class="header-anchor" href="#_2026-10-23-—-toffler-parents-ipo-note-not-a-miss" aria-label="Permalink to &quot;2026-10-23 — Toffler parents&#39; IPO (note, not a miss)&quot;">​</a></h2><p><strong>Point:</strong> In Example 3 (Erin Toffler gives her parents&#39; fee-paying account IPO shares last), <strong>III(B) Fair Dealing</strong> applies alongside <strong>VI(B) Priority of Transactions</strong>.</p>',39)])])}const m=t(s,[["render",r]]);export{h as __pageData,m as default};
